import { OTPS_COLLECTION_NAME, db } from '~/src/mongo.js'

/**
 * @typedef {object} OtpDocument
 * @property {unknown} _id - generated by Mongo
 * @property {string} uid - the interaction uid the code was issued for
 * @property {string} purpose - the authority granted (JOURNEY_CHALLENGE)
 * @property {string} target - lowercased email the code was sent to
 * @property {string} codeHash - argon2 hash (plaintext is never stored)
 * @property {number} attempts - failed verification attempts so far
 * @property {boolean} verified - correct code entered, completion pending
 * @property {boolean} consumed - authority spent or burned
 * @property {Date} createdAt - when the record was first minted
 * @property {Date} expireAt - checked in-app; Mongo TTL is GC only
 */

/**
 * The otps collection (resolved lazily — the `db` live binding is only
 * assigned once `prepareDb` has run)
 */
function coll() {
  return /** @type {Collection<OtpDocument>} */ (
    db.collection(OTPS_COLLECTION_NAME)
  )
}

/**
 * @param {Filter<OtpDocument>} filter
 */
export function findOne(filter) {
  return coll().findOne(filter)
}

/**
 * Upserts the record for a {uid, purpose} key — the unique index makes this
 * "one live code per authority per interaction" (resend overwrites)
 * @param {{ uid: string, purpose: string }} key
 * @param {MatchKeysAndValues<OtpDocument>} fields
 */
export async function upsert(key, fields) {
  await coll().updateOne(
    key,
    { $set: fields, $setOnInsert: { createdAt: new Date() } },
    { upsert: true }
  )
}

/**
 * @param {Filter<OtpDocument>} filter
 * @param {MatchKeysAndValues<OtpDocument>} fields
 */
export async function update(filter, fields) {
  await coll().updateOne(filter, { $set: fields })
}

/**
 * Atomically increments the attempt counter, returning the updated record
 * @param {Filter<OtpDocument>} filter
 * @returns {Promise<OtpDocument | null>} null when no record matches
 */
export function incrementAttempts(filter) {
  return coll().findOneAndUpdate(
    filter,
    { $inc: { attempts: 1 } },
    { returnDocument: 'after' }
  )
}

/**
 * @import { Collection, Filter, MatchKeysAndValues } from 'mongodb'
 */
